actions.script:
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
// newest first: by consentDate, then by id (sequenced, so a later row has the larger id)
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
// the purposes that solicit through each kind of address
const solicitationPurposes = {CmtEmailAddress: ['PcpMarketingEmail'], CmtTelecomNumber: ['PcpSms', 'PcpPhone']}
partyConsentId = null
allowSolicitation = null
solicitationUpdatedCount = 0
const userId = ec.user.userId || null
const enumIn = (enumId, enumTypeId) => !!enumId && ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId)
        .condition('enumTypeId', enumTypeId).useCache(true).one() != null
if (!enumIn(purposeEnumId, 'PartyConsentPurpose')) { ec.message.addError(`Unknown consent purpose ${purposeEnumId}`); return }
if (statusId !== 'PconGranted' && statusId !== 'PconWithdrawn') {
    ec.message.addError(`A consent is PconGranted or PconWithdrawn, not ${statusId}`); return }
if (!sourceEnumId) sourceEnumId = userId ? 'PcsStaff' : 'PcsApi'
if (!enumIn(sourceEnumId, 'PartyConsentSource')) { ec.message.addError(`Unknown consent source ${sourceEnumId}`); return }
const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
// a personal contact is its owner's; the anonymous unsubscribe services run with no user
if (party == null || (userId && party.privateOwnerUserId && party.privateOwnerUserId !== userId)) {
    ec.message.addError(`Party ${partyId} not found`); return }
let contactMech = null
if (contactMechId) {
    if (ec.entity.find('mantle.party.contact.PartyContactMech').condition({partyId: partyId, contactMechId: contactMechId}).count() === 0) {
        ec.message.addError(`Contact information ${contactMechId} is not party ${partyId}'s`); return }
    contactMech = ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechId', contactMechId).one()
}
if (contactListId && ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one() == null) {
    ec.message.addError(`Contact list ${contactListId} not found`); return }

partyConsentId = ec.service.sync().name('create#mantle.party.PartyConsent').parameters({partyId: partyId,
    contactMechId: contactMechId || null, purposeEnumId: purposeEnumId, statusId: statusId,
    consentDate: consentDate || ec.user.nowTimestamp, sourceEnumId: sourceEnumId, evidenceText: evidenceText || null,
    contactListId: contactListId || null, userId: userId, comments: comments || null}).call()?.partyConsentId ?? null
if (ec.message.hasError()) return

// allowSolicitation follows the marketing purposes of the address
if (!updateSolicitation || contactMech == null || contactListId) return
const purposes = solicitationPurposes[contactMech.contactMechTypeEnumId] || []
if (!purposes.includes(purposeEnumId)) return
const rows = Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId)
        .condition('contactMechId', contactMechId).condition('purposeEnumId', 'in', purposes).condition('contactListId', null).list())
rows.sort(newestFirst)
const latest = {}
for (const row of rows) if (!latest[row.purposeEnumId]) latest[row.purposeEnumId] = row
allowSolicitation = Object.values(latest).some((row) => row.statusId === 'PconGranted') ? 'Y' : 'N'
const pcms = Array.from(ec.entity.find('mantle.party.contact.PartyContactMech').condition('partyId', partyId)
        .condition('contactMechId', contactMechId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
const done = new Set()
for (const pcm of pcms) {
    if (pcm.allowSolicitation === allowSolicitation || done.has(pcm.contactMechPurposeId)) continue
    done.add(pcm.contactMechPurposeId)
    ec.service.sync().name('mantle.party.ContactServices.store#PartyContactMech').parameters({partyId: partyId,
        contactMechId: contactMechId, contactMechPurposeId: pcm.contactMechPurposeId, allowSolicitation: allowSolicitation}).call()
    if (ec.message.hasError()) return
    solicitationUpdatedCount++
}

const cf = ec.entity.conditionFactory
const CLP = 'mantle.marketing.contact.ContactListParty'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
consentList = []; addressList = []; listList = []; grantedPurposeEnumIds = []
const userId = ec.user.userId || null
const nowMillis = toMillis(ec.user.nowTimestamp)
const isCurrent = (row) => (row.fromDate == null || toMillis(row.fromDate) <= nowMillis) &&
        (row.thruDate == null || toMillis(row.thruDate) > nowMillis)
const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
if (party == null || (userId && party.privateOwnerUserId && party.privateOwnerUserId !== userId)) {
    ec.message.addError(`Party ${partyId} not found`); return }

const entry = (row) => ({partyConsentId: row.partyConsentId, contactMechId: row.contactMechId ?? null,
    purposeEnumId: row.purposeEnumId, statusId: row.statusId, granted: row.statusId === 'PconGranted',
    consentDate: row.consentDate ?? null, sourceEnumId: row.sourceEnumId ?? null, evidenceText: row.evidenceText ?? null,
    contactListId: row.contactListId ?? null, userId: row.userId ?? null, comments: row.comments ?? null})
const rows = Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId).list())
rows.sort(newestFirst)
const current = new Map()
const lastByList = new Map()
for (const row of rows) {
    if (row.contactListId) { if (!lastByList.has(row.contactListId)) lastByList.set(row.contactListId, row); continue }
    const key = `${row.contactMechId || ''}|${row.purposeEnumId}`
    if (!current.has(key)) current.set(key, row)
}
consentList = Array.from(current.values()).map(entry)
grantedPurposeEnumIds = Array.from(new Set(consentList.filter((consent) => consent.granted).map((consent) => consent.purposeEnumId)))

// the addresses: current email addresses and phone numbers, then earlier ones with consent rows
const phoneText = (tn) => [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ')
const addresses = new Map()
const currentDate = cf.makeConditionDate('fromDate', 'thruDate', null)
for (const info of ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId).condition(currentDate)
        .condition('contactMechTypeEnumId', 'in', ['CmtEmailAddress', 'CmtTelecomNumber']).orderBy('fromDate').list()) {
    let address = addresses.get(info.contactMechId)
    if (address == null) {
        address = {contactMechId: info.contactMechId, contactMechTypeEnumId: info.contactMechTypeEnumId,
            addressText: info.infoString ?? null, contactMechPurposeIds: [], allowSolicitation: null, isCurrent: true, consentList: []}
        addresses.set(info.contactMechId, address)
    }
    address.contactMechPurposeIds.push(info.contactMechPurposeId)
    // Y on any row wins, then N
    if (info.allowSolicitation === 'Y' || (info.allowSolicitation === 'N' && address.allowSolicitation !== 'Y'))
        address.allowSolicitation = info.allowSolicitation
}
for (const consent of consentList) {
    if (!consent.contactMechId || addresses.has(consent.contactMechId)) continue
    const mech = ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechId', consent.contactMechId).one()
    addresses.set(consent.contactMechId, {contactMechId: consent.contactMechId, contactMechTypeEnumId: mech?.contactMechTypeEnumId ?? null,
        addressText: mech?.infoString ?? null, contactMechPurposeIds: [], allowSolicitation: null, isCurrent: false, consentList: []})
}
for (const address of addresses.values()) {
    if (address.contactMechTypeEnumId === 'CmtTelecomNumber') {
        const tn = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId', address.contactMechId).one()
        if (tn != null) address.addressText = phoneText(tn)
    }
    address.consentList = consentList.filter((consent) => consent.contactMechId === address.contactMechId)
}
addressList = Array.from(addresses.values())

// the consent lists the party has a row on
const memberRows = Array.from(ec.entity.find(CLP).condition('partyId', partyId).orderBy('-fromDate').list())
const listIds = Array.from(new Set(memberRows.map((row) => row.contactListId)))
if (listIds.length === 0) return
let ownerFilter = undefined
if (sameOwnerAsListId) {
    const ownerList = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', sameOwnerAsListId).one()
    ownerFilter = ownerList?.ownerPartyId ?? null
}
// a mailbox is membership, not consent, until it has members by email
const emailMembers = (contactListId) => ec.entity.find(CLP).condition('contactListId', contactListId)
        .condition('preferredContactMechId', 'is-not-null', null).condition(currentDate).count() > 0
const lists = Array.from(ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', 'in', listIds)
        .orderBy('contactListName').list())
for (const list of lists) {
    if (list.contactListTypeEnumId === 'MAILBOX' && !emailMembers(list.contactListId)) continue
    if (ownerFilter !== undefined && (list.ownerPartyId ?? null) !== ownerFilter) continue
    const isArchived = list.archivedDate != null && toMillis(list.archivedDate) <= nowMillis
    if (isArchived && !includeArchived) continue
    const mine = memberRows.filter((row) => row.contactListId === list.contactListId)
    const row = mine.find(isCurrent) || mine[0]
    const last = lastByList.get(list.contactListId)
    listList.push({contactListId: list.contactListId, contactListName: list.contactListName ?? null,
        description: list.description ?? null, contactListTypeEnumId: list.contactListTypeEnumId ?? null,
        contactMechTypeEnumId: list.contactMechTypeEnumId ?? null, ownerPartyId: list.ownerPartyId ?? null,
        isArchived: isArchived, statusId: row.statusId ?? null, isCurrent: isCurrent(row),
        subscribed: isCurrent(row) && ['CLPT_ACCEPTED', 'CLPT_IN_USE'].includes(row.statusId),
        unsubscribePending: isCurrent(row) && row.statusId === 'CLPT_UNSUBS_PENDING',
        fromDate: row.fromDate ?? null, thruDate: row.thruDate ?? null, preferredContactMechId: row.preferredContactMechId ?? null,
        lastConsentStatusId: last?.statusId ?? null, lastChangeDate: last?.consentDate ?? null, lastSourceEnumId: last?.sourceEnumId ?? null})
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
historyList = []
historyListCount = 0
const userId = ec.user.userId || null
const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
if (party == null || (userId && party.privateOwnerUserId && party.privateOwnerUserId !== userId)) {
    ec.message.addError(`Party ${partyId} not found`); return }
let find = ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId)
if (contactMechId) find = find.condition('contactMechId', contactMechId)
if (purposeEnumId) find = find.condition('purposeEnumId', purposeEnumId)
if (contactListId) find = find.condition('contactListId', contactListId)
const rows = Array.from(find.list())
rows.sort(newestFirst)
historyListCount = rows.length
const pageIndexInt = pageNoLimit ? 0 : Math.max(0, Math.trunc(Number(pageIndex || 0)))
const pageSizeInt = Math.max(1, Math.trunc(Number(pageSize || 50)))
historyListPageIndex = pageIndexInt
historyListPageSize = pageNoLimit ? Math.max(1, historyListCount) : pageSizeInt
historyListPageMaxIndex = Math.max(0, Math.ceil(historyListCount / historyListPageSize) - 1)
historyListPageRangeLow = historyListCount ? pageIndexInt * historyListPageSize + 1 : 0
historyListPageRangeHigh = Math.min(historyListCount, (pageIndexInt + 1) * historyListPageSize)
const page = pageNoLimit ? rows : rows.slice(pageIndexInt * pageSizeInt, (pageIndexInt + 1) * pageSizeInt)

const enumText = (enumId) => enumId ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId).useCache(true).one()?.description ?? enumId) : null
const statusText = (statusId) => statusId ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', statusId).useCache(true).one()?.description ?? statusId) : null
const phoneText = (tn) => [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ')
const addressTexts = new Map()
const addressText = (id) => {
    if (!id) return null
    if (!addressTexts.has(id)) {
        const mech = ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechId', id).one()
        let text = mech?.infoString ?? null
        if (mech?.contactMechTypeEnumId === 'CmtTelecomNumber') {
            const tn = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId', id).one()
            if (tn != null) text = phoneText(tn)
        }
        addressTexts.set(id, text)
    }
    return addressTexts.get(id)
}
const listNames = new Map()
const listName = (id) => {
    if (!id) return null
    if (!listNames.has(id)) listNames.set(id, ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', id).one()?.contactListName ?? id)
    return listNames.get(id)
}
const userNames = new Map()
const userName = (id) => {
    if (!id) return null
    if (!userNames.has(id)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', id).useCache(true).one()
        userNames.set(id, account?.userFullName || account?.username || id)
    }
    return userNames.get(id)
}
historyList = page.map((row) => ({partyConsentId: row.partyConsentId, consentDate: row.consentDate ?? null,
    purposeEnumId: row.purposeEnumId, purposeDescription: enumText(row.purposeEnumId), statusId: row.statusId,
    statusDescription: statusText(row.statusId), granted: row.statusId === 'PconGranted', sourceEnumId: row.sourceEnumId ?? null,
    sourceDescription: enumText(row.sourceEnumId), evidenceText: row.evidenceText ?? null, comments: row.comments ?? null,
    contactMechId: row.contactMechId ?? null, addressText: addressText(row.contactMechId), contactListId: row.contactListId ?? null,
    contactListName: listName(row.contactListId), userId: row.userId ?? null, userName: userName(row.userId)}))

const cf = ec.entity.conditionFactory
const CLP = 'mantle.marketing.contact.ContactListParty'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
consentList = []
consentListCount = 0
csvText = null
const userId = ec.user.userId || null
const nowMillis = toMillis(ec.user.nowTimestamp)
const currentDate = cf.makeConditionDate('fromDate', 'thruDate', null)
const isCurrent = (row) => (row.fromDate == null || toMillis(row.fromDate) <= nowMillis) &&
        (row.thruDate == null || toMillis(row.thruDate) > nowMillis)
const addressTypes = ['CmtEmailAddress', 'CmtTelecomNumber']
const pageIndexInt = pageNoLimit || exportCsv ? 0 : Math.max(0, Math.trunc(Number(pageIndex || 0)))
const pageSizeInt = Math.max(1, Math.trunc(Number(pageSize || 50)))
const listStatus = statusId && String(statusId).startsWith('CLPT_') ? statusId : null
const consentStatus = statusId && !listStatus ? statusId : null

// the consent lists: every list but a mailbox without members by email
const allLists = Array.from(ec.entity.find('mantle.marketing.contact.ContactList').list())
const mailboxIds = allLists.filter((list) => list.contactListTypeEnumId === 'MAILBOX').map((list) => list.contactListId)
const emailMailboxIds = new Set(mailboxIds.length ? Array.from(ec.entity.find(CLP).condition('contactListId', 'in', mailboxIds)
        .condition('preferredContactMechId', 'is-not-null', null).condition(currentDate).selectField('contactListId')
        .distinct(true).list()).map((row) => row.contactListId) : [])
const listById = new Map(allLists.filter((list) => list.contactListTypeEnumId !== 'MAILBOX' || emailMailboxIds.has(list.contactListId))
        .map((list) => [list.contactListId, list]))
const consentListIds = Array.from(listById.keys())
if (contactListId && !listById.has(contactListId)) return

// the candidate parties, narrowed by the filters a query can apply
let candidates = null
const narrow = (ids) => {
    const set = new Set(ids)
    candidates = candidates == null ? set : new Set(Array.from(candidates).filter((id) => set.has(id)))
}
const partyIdsOf = (find) => Array.from(find.selectField('partyId').distinct(true).list()).map((row) => row.partyId)
if (contactListId) narrow(partyIdsOf(ec.entity.find(CLP).condition('contactListId', contactListId)))
if (changedFromDate || changedThruDate) {
    let find = ec.entity.find('mantle.party.PartyConsent')
    if (changedFromDate) find = find.condition('consentDate', 'greater-equals', new Date(toMillis(changedFromDate)))
    if (changedThruDate) find = find.condition('consentDate', 'less', new Date(toMillis(changedThruDate)))
    narrow(partyIdsOf(find))
}
if (allowSolicitation) narrow(partyIdsOf(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition(currentDate)
        .condition('contactMechTypeEnumId', 'in', addressTypes).condition('allowSolicitation', allowSolicitation)))
if (candidates == null) {
    candidates = new Set(partyIdsOf(ec.entity.find('mantle.party.PartyConsent')))
    if (consentListIds.length) for (const id of partyIdsOf(ec.entity.find(CLP).condition('contactListId', 'in', consentListIds))) candidates.add(id)
    for (const id of partyIdsOf(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition(currentDate)
            .condition('contactMechTypeEnumId', 'in', addressTypes).condition('allowSolicitation', 'is-not-null', null))) candidates.add(id)
}
const candidateIds = Array.from(candidates)

// each candidate's row, read a chunk of parties at a time
const phoneText = (tn) => [tn.countryCode ? '+' + tn.countryCode : null, tn.areaCode, tn.contactNumber].filter((part) => part).join(' ')
const phoneRank = ['PhonePrimary', 'PhoneMobile']
const rank = (purposeId) => { const index = phoneRank.indexOf(purposeId); return index < 0 ? phoneRank.length : index }
const group = (list, key) => {
    const map = new Map()
    for (const item of list) { const id = item[key]; if (!map.has(id)) map.set(id, []); map.get(id).push(item) }
    return map
}
const rows = []
for (let start = 0; start < candidateIds.length; start += 200) {
    const ids = candidateIds.slice(start, start + 200)
    const parties = Array.from(ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', ids).list())
    const infosByParty = group(Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', 'in', ids)
            .condition(currentDate).condition('contactMechTypeEnumId', 'in', addressTypes).orderBy('fromDate').list()), 'partyId')
    const phonesByParty = group(Array.from(ec.entity.find('mantle.party.contact.PartyContactMechTelecomNumber').condition('partyId', 'in', ids)
            .condition(currentDate).orderBy('fromDate').list()), 'partyId')
    const consentsByParty = group(Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', 'in', ids).list()), 'partyId')
    const membersByParty = consentListIds.length ? group(Array.from(ec.entity.find(CLP).condition('partyId', 'in', ids)
            .condition('contactListId', 'in', consentListIds).orderBy('-fromDate').list()), 'partyId') : new Map()
    for (const party of parties) {
        if (party.privateOwnerUserId && party.privateOwnerUserId !== userId) continue
        if (party.mergedToPartyId) continue
        const infos = infosByParty.get(party.partyId) || []
        const emails = infos.filter((info) => info.contactMechTypeEnumId === 'CmtEmailAddress' && info.infoString)
                .sort((a, b) => (a.contactMechPurposeId === 'EmailPrimary' ? 0 : 1) - (b.contactMechPurposeId === 'EmailPrimary' ? 0 : 1))
        const phones = (phonesByParty.get(party.partyId) || []).slice().sort((a, b) => rank(a.contactMechPurposeId) - rank(b.contactMechPurposeId))
        const flagOf = (contactMechId) => {
            const flags = infos.filter((info) => info.contactMechId === contactMechId).map((info) => info.allowSolicitation)
            return flags.includes('Y') ? 'Y' : flags.includes('N') ? 'N' : null
        }
        const consents = (consentsByParty.get(party.partyId) || []).slice().sort(newestFirst)
        const current = new Map()
        for (const consent of consents) {
            if (consent.contactListId) continue
            const key = `${consent.contactMechId || ''}|${consent.purposeEnumId}`
            if (!current.has(key)) current.set(key, consent)
        }
        const states = Array.from(current.values())
        const granted = Array.from(new Set(states.filter((state) => state.statusId === 'PconGranted').map((state) => state.purposeEnumId)))
        const withdrawn = Array.from(new Set(states.filter((state) => state.statusId === 'PconWithdrawn' && !granted.includes(state.purposeEnumId))
                .map((state) => state.purposeEnumId)))
        const members = membersByParty.get(party.partyId) || []
        const lists = []
        for (const [id, listRows] of group(members, 'contactListId')) {
            const row = listRows.find(isCurrent) || listRows[0]
            const list = listById.get(id)
            lists.push({contactListId: id, contactListName: list?.contactListName ?? id, statusId: row.statusId ?? null,
                subscribed: isCurrent(row) && ['CLPT_ACCEPTED', 'CLPT_IN_USE'].includes(row.statusId)})
        }
        lists.sort((a, b) => String(a.contactListName).localeCompare(String(b.contactListName)))
        const last = consents[0] || null
        const email = emails[0] || null
        const phone = phones[0] || null
        rows.push({partyId: party.partyId, partyTypeEnumId: party.partyTypeEnumId ?? null,
            partyName: ec.resource.expand('PartyFullNameTemplate', '', party).trim() || party.partyId,
            emailAddress: email?.infoString ?? null, emailContactMechId: email?.contactMechId ?? null,
            emailAllowSolicitation: email ? flagOf(email.contactMechId) : null,
            phoneNumber: phone ? phoneText(phone) : null, phoneContactMechId: phone?.contactMechId ?? null,
            phoneAllowSolicitation: phone ? flagOf(phone.contactMechId) : null,
            listList: lists, grantedPurposeEnumIds: granted, withdrawnPurposeEnumIds: withdrawn,
            lastChangeDate: last?.consentDate ?? null, lastSourceEnumId: last?.sourceEnumId ?? null, lastStatusId: last?.statusId ?? null,
            lastPurposeEnumId: last?.purposeEnumId ?? null, lastContactListId: last?.contactListId ?? null,
            _search: [party.partyId, ec.resource.expand('PartyFullNameTemplate', '', party), party.organizationName,
                ...infos.map((info) => info.infoString), ...(phonesByParty.get(party.partyId) || []).map((tn) =>
                    `${tn.countryCode ?? ''}${tn.areaCode ?? ''}${tn.contactNumber ?? ''}`)].filter((part) => part).join(' ').toLowerCase(),
            _flags: infos.map((info) => info.allowSolicitation), _states: states})
    }
}

// the filters on what the rows hold
const needle = text ? String(text).trim().toLowerCase() : ''
const needleDigits = needle.replace(/[^0-9]/g, '')
const matches = rows.filter((row) => {
    if (needle && !row._search.includes(needle) && !(needleDigits.length >= 3 && needleDigits === needle.replace(/[\s()+.-]/g, '')
            && row._search.replace(/[^0-9 ]/g, '').includes(needleDigits))) return false
    if (contactListId && !row.listList.some((list) => list.contactListId === contactListId)) return false
    if (listStatus && !row.listList.some((list) => (!contactListId || list.contactListId === contactListId) && list.statusId === listStatus)) return false
    if (consentStatus) {
        if (purposeEnumId) {
            const state = consentStatus === 'PconGranted' ? row.grantedPurposeEnumIds.includes(purposeEnumId)
                    : row.withdrawnPurposeEnumIds.includes(purposeEnumId)
            if (!state) return false
        } else if (!row._states.some((state) => state.statusId === consentStatus)) return false
    } else if (purposeEnumId && !row.grantedPurposeEnumIds.includes(purposeEnumId)) return false
    if (allowSolicitation && !row._flags.includes(allowSolicitation)) return false
    return true
})

// order, then a page
const descending = String(orderByField || '').startsWith('-')
const sortField = String(orderByField || '-lastChangeDate').replace(/^[-+^]+/, '') || 'lastChangeDate'
const sortValue = (row) => sortField === 'lastChangeDate' ? (toMillis(row.lastChangeDate) ?? -Infinity)
        : String(row[sortField] ?? '').toLowerCase()
matches.sort((a, b) => {
    const left = sortValue(a), right = sortValue(b)
    const order = left < right ? -1 : left > right ? 1 : String(a.partyName).localeCompare(String(b.partyName))
    return descending ? -order : order
})
for (const row of matches) { delete row._search; delete row._flags; delete row._states }
consentListCount = matches.length
const pageAll = pageNoLimit || exportCsv
consentListPageIndex = pageIndexInt
consentListPageSize = pageAll ? Math.max(1, consentListCount) : pageSizeInt
consentListPageMaxIndex = Math.max(0, Math.ceil(consentListCount / consentListPageSize) - 1)
consentListPageRangeLow = consentListCount ? pageIndexInt * consentListPageSize + 1 : 0
consentListPageRangeHigh = Math.min(consentListCount, (pageIndexInt + 1) * consentListPageSize)
consentList = pageAll ? matches : matches.slice(pageIndexInt * pageSizeInt, (pageIndexInt + 1) * pageSizeInt)
if (!exportCsv) return

// the CSV export: every match, with descriptions, dates as ISO time stamps in UTC
const enumText = (enumId) => enumId ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId).useCache(true).one()?.description ?? enumId) : ''
const statusText = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description ?? id) : ''
const dateText = (value) => { const millis = toMillis(value); return millis == null ? '' : new Date(millis).toISOString() }
const quote = (value) => {
    const textValue = value == null ? '' : String(value)
    return /[",\r\n]/.test(textValue) ? `"${textValue.replace(/"/g, '""')}"` : textValue
}
const header = ['Party ID', 'Name', 'Email', 'Email Allow Solicitation', 'Phone', 'Phone Allow Solicitation', 'Lists',
    'Purposes Granted', 'Purposes Withdrawn', 'Last Change', 'Last Change Status', 'Last Change Purpose', 'Last Change Source']
const lines = [header.map(quote).join(',')]
for (const row of matches) {
    lines.push([row.partyId, row.partyName, row.emailAddress, row.emailAllowSolicitation, row.phoneNumber, row.phoneAllowSolicitation,
        row.listList.map((list) => `${list.contactListName}: ${statusText(list.statusId)}`).join('; '),
        row.grantedPurposeEnumIds.map(enumText).join('; '), row.withdrawnPurposeEnumIds.map(enumText).join('; '),
        dateText(row.lastChangeDate), statusText(row.lastStatusId), enumText(row.lastPurposeEnumId), enumText(row.lastSourceEnumId)]
        .map(quote).join(','))
}
csvText = lines.join('\r\n') + '\r\n'
fileName = 'consents.csv'
contentType = 'text/csv'

const cf = ec.entity.conditionFactory
const CLP = 'mantle.marketing.contact.ContactListParty'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
statusId = null; previousStatusId = null; changed = false; consentRecorded = false; verifyEmailSent = false
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)
const currentDate = cf.makeConditionDate('fromDate', 'thruDate', null)
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
if (list == null) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listName = list.contactListName || contactListId
if (list.contactListTypeEnumId === 'MAILBOX' && ec.entity.find(CLP).condition('contactListId', contactListId)
        .condition('preferredContactMechId', 'is-not-null', null).condition(currentDate).count() === 0) {
    ec.message.addError(`${listName} is a mailbox: its members join and leave it`); return }
const purposeEnumId = list.contactMechTypeEnumId === 'CmtTelecomNumber' ? 'PcpSms' : 'PcpMarketingEmail'
const rows = Array.from(ec.entity.find(CLP).condition('contactListId', contactListId).condition('partyId', partyId)
        .condition(currentDate).orderBy('-fromDate').list())
const latest = rows[0] || null
previousStatusId = latest?.statusId ?? null
if (!contactMechId) contactMechId = latest?.preferredContactMechId || null
// an address that is not the party's is left off the consent row
if (contactMechId && ec.entity.find('mantle.party.contact.PartyContactMech').condition({partyId: partyId, contactMechId: contactMechId}).count() === 0) {
    ec.logger.warn(`Consent for party ${partyId} on list ${contactListId}: contact information ${contactMechId} is not the party's, left off`)
    contactMechId = null
}
const consents = Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId).list())
consents.sort(newestFirst)
const lastListConsent = consents.find((row) => row.contactListId === contactListId) || null
const record = (consentStatusId, extraEvidence, forList) => {
    ec.service.sync().name('mantle.party.ConsentServices.store#PartyConsent').parameters({partyId: partyId,
        contactMechId: contactMechId, purposeEnumId: purposeEnumId, statusId: consentStatusId, sourceEnumId: sourceEnumId,
        evidenceText: [evidenceText, extraEvidence].filter((part) => part).join('; ') || null,
        comments: comments ? String(comments).trim().slice(0, 255) || null : null,
        contactListId: forList ? contactListId : null}).call()
}

if (subscribe) {
    if (list.archivedDate != null && toMillis(list.archivedDate) <= nowMillis) { ec.message.addError(`${listName} is archived`); return }
    if (latest && ['CLPT_ACCEPTED', 'CLPT_IN_USE'].includes(latest.statusId)) {
        statusId = latest.statusId
    } else if (latest) {
        latest.set('statusId', 'CLPT_ACCEPTED')
        latest.set('optInVerifyCode', null)
        if (contactMechId && !latest.preferredContactMechId) latest.set('preferredContactMechId', contactMechId)
        latest.update()
        statusId = 'CLPT_ACCEPTED'
        changed = true
    } else {
        ec.service.sync().name('create#mantle.marketing.contact.ContactListParty').parameters({contactListId: contactListId,
            partyId: partyId, fromDate: now, statusId: 'CLPT_ACCEPTED', preferredContactMechId: contactMechId}).call()
        if (ec.message.hasError()) return
        statusId = 'CLPT_ACCEPTED'
        changed = true
    }
    if (lastListConsent?.statusId !== 'PconGranted') {
        record('PconGranted', null, true)
        if (ec.message.hasError()) return
        consentRecorded = true
    }
    // a list subscription brings back the address's marketing consent when it was withdrawn
    if (contactMechId) {
        const addressState = consents.find((row) => !row.contactListId && row.contactMechId === contactMechId && row.purposeEnumId === purposeEnumId)
        if (addressState?.statusId === 'PconWithdrawn') {
            record('PconGranted', `Subscribed to ${listName}`, false)
            if (ec.message.hasError()) return
        }
    }
    return
}

let isConfirmed = !!confirmed
if (verifyCode) {
    const pendingRow = rows.find((row) => row.statusId === 'CLPT_UNSUBS_PENDING' && row.optInVerifyCode && row.optInVerifyCode === String(verifyCode))
    if (pendingRow == null) { ec.message.addError('The confirmation code does not match'); return }
    isConfirmed = true
}
const needsConfirm = !isConfirmed && ec.entity.find('mantle.marketing.contact.ContactListEmail').condition('contactListId', contactListId)
        .condition('emailTypeEnumId', 'CONT_UNSUB_VER').condition(currentDate).count() > 0
const target = needsConfirm ? 'CLPT_UNSUBS_PENDING' : 'CLPT_UNSUBSCRIBED'
// one new code for the rows going to pending, the one the verification email carries
let newVerifyCode = null
if (rows.length === 0) {
    ec.service.sync().name('create#mantle.marketing.contact.ContactListParty').parameters({contactListId: contactListId,
        partyId: partyId, fromDate: now, statusId: 'CLPT_UNSUBSCRIBED', preferredContactMechId: contactMechId}).call()
    if (ec.message.hasError()) return
    statusId = 'CLPT_UNSUBSCRIBED'
    changed = true
} else {
    for (const row of rows) {
        if (row.statusId === 'CLPT_UNSUBSCRIBED' || row.statusId === target) continue
        row.set('statusId', target)
        if (target === 'CLPT_UNSUBS_PENDING') {
            if (!newVerifyCode) newVerifyCode = ec.user.randomString(20)
            row.set('optInVerifyCode', newVerifyCode)
        }
        row.update()
        changed = true
    }
    statusId = rows.some((row) => row.statusId === 'CLPT_UNSUBSCRIBED') && !rows.some((row) => row.statusId !== 'CLPT_UNSUBSCRIBED')
            ? 'CLPT_UNSUBSCRIBED' : rows[0].statusId
}
if (lastListConsent?.statusId !== 'PconWithdrawn') {
    record('PconWithdrawn', statusId === 'CLPT_UNSUBS_PENDING' ? 'pending confirmation' : null, true)
    if (ec.message.hasError()) return
    consentRecorded = true
}

// the verification email of an unsubscribe that waits for its confirmation, a probe: one not sent is logged
if (newVerifyCode) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('mantle.party.ConsentServices.send#UnsubscribeVerifyEmail').parameters({contactListId: contactListId,
            partyId: partyId, contactMechId: contactMechId || latest?.preferredContactMechId || null, verifyCode: newVerifyCode,
            baseUrl: baseUrl || null}).requireNewTransaction(true).call()
        if (ec.message.hasError()) ec.logger.error(`Unsubscribe verification email to party ${partyId} for list ${contactListId} not sent: ${ec.message.getErrorsString()}`)
        else verifyEmailSent = !!out?.sent
    } catch (err) {
        ec.logger.error(`Unsubscribe verification email to party ${partyId} for list ${contactListId} not sent: ${String(err && err.message ? err.message : err).trim()}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

const cf = ec.entity.conditionFactory
sent = false
const currentDate = cf.makeConditionDate('fromDate', 'thruDate', null)
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
if (list == null) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listEmail = Array.from(ec.entity.find('mantle.marketing.contact.ContactListEmail').condition('contactListId', contactListId)
        .condition('emailTypeEnumId', 'CONT_UNSUB_VER').condition(currentDate).orderBy('-fromDate').list()).find((row) => row.emailTemplateId)
const templateId = listEmail?.emailTemplateId || (list.verifyEmailFrom ? 'MANTLE_UNSUBSCRIBE_VERIFY' : null)
if (!templateId) { ec.logger.warn(`List ${contactListId} requires unsubscribe confirmation but has no Unsubscribe Verify template or verifyEmailFrom; none sent to party ${partyId}`); return }
const template = ec.entity.find('moqui.basic.email.EmailTemplate').condition('emailTemplateId', templateId).one()
if (template == null) { ec.message.addError(`Email template ${templateId} not found`); return }
// the address: the given one when it is an email address of the party, else its primary email
const emailOf = (id) => {
    if (!id) return null
    const info = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId).condition('contactMechId', id)
            .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(currentDate).list())[0]
    return info?.infoString ? info : null
}
let address = emailOf(contactMechId)
if (address == null) {
    const infos = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId)
            .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(currentDate).orderBy('fromDate').list()).filter((info) => info.infoString)
    address = infos.find((info) => info.contactMechPurposeId === 'EmailPrimary') || infos[0] || null
}
if (address == null) { ec.logger.warn(`Unsubscribe verification for party ${partyId} on list ${contactListId}: no email address, none sent`); return }
let root = String(baseUrl || '').trim()
if (!root && template.webHostName) root = `https://${template.webHostName}`
if (!root && template.emailServerId) root = String(ec.entity.find('moqui.basic.email.EmailServer')
        .condition('emailServerId', template.emailServerId).useCache(true).one()?.webBaseUrl || '').trim()
const link = ec.service.sync().name('mantle.party.ConsentServices.create#UnsubscribeToken').parameters({contactListId: contactListId,
    partyId: partyId, contactMechId: address.contactMechId, baseUrl: root || null, validDays: 14}).call()
if (ec.message.hasError()) return
verifyUrl = `${link.unsubscribeUrl}?verifyCode=${encodeURIComponent(verifyCode)}`
let organizationName = null
if (list.ownerPartyId) {
    const owner = ec.entity.find('mantle.party.PartyDetail').condition('partyId', list.ownerPartyId).one()
    organizationName = owner == null ? null : (owner.organizationName || ec.resource.expand('PartyFullNameTemplate', '', owner).trim() || null)
}
const listName = list.contactListName || contactListId
const encode = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const params = {verifyUrl: verifyUrl, verifyCode: verifyCode, contactListId: contactListId, contactListName: listName,
    organizationName: organizationName, partyId: partyId, fromAddress: list.verifyEmailFrom || null, fromName: organizationName,
    subject: list.verifyEmailSubject || `Confirm your unsubscribe from ${listName}`}
// a template without a body screen: a short body with the link
const own = !template.bodyScreenLocation
const out = ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({emailTemplateId: template.emailTemplateId,
    toAddresses: address.infoString, createEmailMessage: true, bodyParameters: params,
    body: own ? `<p>Please confirm that you want to stop getting ${encode(listName)}${organizationName ? ' from ' + encode(organizationName) : ''}.</p>`
        + `<p><a href="${encode(verifyUrl)}">Confirm unsubscribe</a></p><p>If you did not ask for this, ignore this email and you stay subscribed.</p>` : null,
    bodyText: own ? `Please confirm that you want to stop getting ${listName}${organizationName ? ' from ' + organizationName : ''}.\n\n`
        + `Confirm unsubscribe: ${verifyUrl}\n\nIf you did not ask for this, ignore this email and you stay subscribed.\n` : null}).call()
if (ec.message.hasError()) return
emailMessageId = out?.emailMessageId ?? null
// a server with no SMTP host keeps the message unsent, with no Message-ID
sent = !!out?.messageId
if (!sent) ec.logger.warn(`Unsubscribe verification email ${emailMessageId} to party ${partyId} for list ${contactListId} was not sent by the mail server`)

const userId = ec.user.userId || null
const userPartyId = ec.user.userAccount?.partyId || null
if (!userId) { ec.message.addError('Subscribing needs a signed-in user; the unsubscribe page uses apply#UnsubscribePreferences'); return }
if (!partyId) partyId = userPartyId
if (!partyId) { ec.message.addError('No party to subscribe'); return }
const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
if (party == null || (party.privateOwnerUserId && party.privateOwnerUserId !== userId)) { ec.message.addError(`Party ${partyId} not found`); return }
if (!sourceEnumId) sourceEnumId = partyId === userPartyId ? 'PcsForm' : 'PcsStaff'
const out = ec.service.sync().name('mantle.party.ConsentServices.set#ContactListPartySubscription').parameters({contactListId: contactListId,
    partyId: partyId, subscribe: true, contactMechId: contactMechId, sourceEnumId: sourceEnumId, evidenceText: evidenceText}).call()
if (ec.message.hasError()) return
statusId = out.statusId; previousStatusId = out.previousStatusId; changed = out.changed

const cf = ec.entity.conditionFactory
const CLP = 'mantle.marketing.contact.ContactListParty'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
statusId = null; unsubscribePending = false; changedList = []; unchangedContactListIds = []; failedContactListIds = []
marketingWithdrawn = false; verifyEmailSent = false
const now = ec.user.nowTimestamp
const reason = reasonText ? String(reasonText).trim().slice(0, 255) || null : null

// the token first, before anything else is read
const invalid = 'This unsubscribe link is not valid or has expired'
const tokenText = token == null ? '' : String(token).trim()
let tokenRow = null
if (tokenText) {
    if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) { ec.message.addError(invalid); return }
    tokenRow = ec.entity.find('mantle.marketing.contact.ContactListToken').condition('tokenHash', ec.user.singleUseCodeHash(tokenText)).one()
    if (tokenRow == null || (tokenRow.thruDate != null && toMillis(tokenRow.thruDate) <= toMillis(now))) { ec.message.addError(invalid); return }
    if (partyId && partyId !== tokenRow.partyId) { ec.message.addError(invalid); return }
}
const oneClick = String(listUnsubscribe || '').trim().toLowerCase() === 'one-click'
// the List-Unsubscribe mailto: an email whose subject carries the token (process#UnsubscribeEmail)
const byMail = String(listUnsubscribe || '').trim().toLowerCase() === 'mailto'
if ((oneClick || byMail) && tokenRow == null) { ec.message.addError('A one-click unsubscribe needs the link token'); return }

let tokenList = null
if (tokenRow != null) {
    partyId = tokenRow.partyId
    if (!contactMechId) contactMechId = tokenRow.contactMechId || null
    else if (contactMechId !== tokenRow.contactMechId) { ec.message.addError(invalid); return }
    // an anonymous visitor's change is the email link's, with the link as its evidence
    if (!sourceEnumId || !ec.user.userId) sourceEnumId = 'PcsEmailLink'
    // the link's own confirmation: only a one-click POST or the mailto's email, or a verifyCode below
    confirmed = oneClick || byMail
    // a Message-ID without its angle brackets, which the evidence parameters take as markup
    const ofMessage = tokenRow.messageId ? ` of message ${String(tokenRow.messageId).replace(/[<>]/g, '')}`
            : tokenRow.communicationEventId ? ` of communication ${tokenRow.communicationEventId}` : ''
    const mailFrom = byMail && evidenceText ? ` from ${String(evidenceText).replace(/[<>]/g, '').trim().slice(0, 200)}` : ''
    evidenceText = oneClick ? `One-click unsubscribe (RFC 8058)${ofMessage}`
            : byMail ? `Unsubscribe by email (List-Unsubscribe mailto)${mailFrom}${ofMessage}` : `Unsubscribe link${ofMessage}`
    tokenList = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', tokenRow.contactListId).one()
    if (tokenList == null) { ec.message.addError(invalid); return }
} else {
    const userId = ec.user.userId || null
    if (!userId) { ec.message.addError('Unsubscribing without a link token needs a signed-in user'); return }
    if (!partyId) { ec.message.addError('Unsubscribing needs a partyId'); return }
    const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
    if (party == null || (party.privateOwnerUserId && party.privateOwnerUserId !== userId)) { ec.message.addError(`Party ${partyId} not found`); return }
    if (!sourceEnumId) sourceEnumId = 'PcsStaff'
}
const sameOwner = (list) => tokenList == null || (list.ownerPartyId ?? null) === (tokenList.ownerPartyId ?? null)

// the lists
let listIds = []
if (allMarketing) {
    const memberIds = Array.from(new Set(Array.from(ec.entity.find(CLP).condition('partyId', partyId)
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('contactListId').distinct(true).list())
            .map((row) => row.contactListId)))
    const lists = memberIds.length ? Array.from(ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', 'in', memberIds)
            .orderBy('contactListName').list()) : []
    listIds = lists.filter((list) => list.contactListTypeEnumId !== 'MAILBOX' && list.contactMechTypeEnumId !== 'CmtTelecomNumber' && sameOwner(list))
            .map((list) => list.contactListId)
} else {
    const targetId = contactListId || tokenRow?.contactListId
    if (!targetId) { ec.message.addError('Unsubscribing needs a contactListId'); return }
    if (tokenRow != null && targetId !== tokenRow.contactListId) {
        // another of the party's lists of the token list's organization, as the preferences page offers
        const other = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', targetId).one()
        if (other == null || !sameOwner(other) || ec.entity.find(CLP).condition('contactListId', targetId).condition('partyId', partyId).count() === 0) {
            ec.message.addError(invalid); return }
    }
    listIds = [targetId]
}

const change = (id, separately) => {
    let call = ec.service.sync().name('mantle.party.ConsentServices.set#ContactListPartySubscription').parameters({contactListId: id,
        partyId: partyId, subscribe: false, contactMechId: contactMechId, sourceEnumId: sourceEnumId, evidenceText: evidenceText,
        comments: reason, confirmed: confirmed, verifyCode: allMarketing ? null : verifyCode, baseUrl: baseUrl || null})
    if (separately) call = call.requireNewTransaction(true)
    return call.call()
}
if (!allMarketing) {
    const out = change(listIds[0], false)
    if (ec.message.hasError()) return
    statusId = out.statusId
    unsubscribePending = statusId === 'CLPT_UNSUBS_PENDING'
    verifyEmailSent = !!out.verifyEmailSent
    if (out.changed) changedList.push({contactListId: listIds[0], statusId: out.statusId, previousStatusId: out.previousStatusId})
    else unchangedContactListIds.push(listIds[0])
} else {
    // each list on its own, so one that fails does not keep the others subscribed
    for (const id of listIds) {
        try {
            const out = change(id, true)
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            if (out.changed) changedList.push({contactListId: id, statusId: out.statusId, previousStatusId: out.previousStatusId})
            else unchangedContactListIds.push(id)
            if (out.statusId === 'CLPT_UNSUBS_PENDING') unsubscribePending = true
            if (out.verifyEmailSent) verifyEmailSent = true
        } catch (err) {
            ec.message.clearErrors()
            ec.logger.error(`Unsubscribe of party ${partyId} from contact list ${id} failed: ${String(err && err.message ? err.message : err).trim()}`)
            failedContactListIds.push(id)
        }
    }
    // and the address, or each email address of the party, withdrawn from marketing email
    let mechIds = contactMechId ? [contactMechId] : Array.from(new Set(Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo')
            .condition('partyId', partyId).condition('contactMechTypeEnumId', 'CmtEmailAddress')
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()).map((info) => info.contactMechId)))
    if (mechIds.length === 0) mechIds = [null]
    const consents = Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId)
            .condition('purposeEnumId', 'PcpMarketingEmail').condition('contactListId', null).list())
    consents.sort(newestFirst)
    for (const mechId of mechIds) {
        const state = consents.find((row) => (row.contactMechId || null) === mechId)
        if (state?.statusId === 'PconWithdrawn') continue
        ec.service.sync().name('mantle.party.ConsentServices.store#PartyConsent').parameters({partyId: partyId, contactMechId: mechId,
            purposeEnumId: 'PcpMarketingEmail', statusId: 'PconWithdrawn', sourceEnumId: sourceEnumId,
            evidenceText: [evidenceText, 'all marketing email'].filter((part) => part).join('; '), comments: reason}).call()
        if (ec.message.hasError()) return
