    tokenRow.update()
}

unsubscribed = false
const subjectText = String(fields?.subject || '').trim()
const found = /^unsubscribe\s+([A-Za-z0-9_-]{16,128})$/i.exec(subjectText)
if (!found) return
const sender = String(fields?.from || '').replace(/[<>]/g, ' ').replace(/\s+/g, ' ').trim()
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty').parameters({token: found[1],
        listUnsubscribe: 'Mailto', evidenceText: sender || null}).requireNewTransaction(true).call()
    if (ec.message.hasError()) ec.logger.warn(`Unsubscribe email from ${sender || 'an unknown sender'} not applied: ${ec.message.getErrorsString()}`)
    else unsubscribed = !!out
} catch (err) {
    ec.logger.warn(`Unsubscribe email from ${sender || 'an unknown sender'} not applied: ${String(err && err.message ? err.message : err).trim()}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

unsubscribedCount = 0; pendingCount = 0; unchangedCount = 0; failedPartyIdList = []
for (const id of Array.from(new Set(Array.from(partyIdList || []).map((value) => String(value).trim()).filter((value) => value)))) {
    try {
        const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty').parameters({contactListId: contactListId,
            partyId: id, sourceEnumId: sourceEnumId, evidenceText: evidenceText, confirmed: confirmed}).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (!out.changedList?.length) unchangedCount++
        else if (out.unsubscribePending) pendingCount++
        else unsubscribedCount++
    } catch (err) {
        ec.message.clearErrors()
        ec.logger.error(`Unsubscribe of party ${id} from contact list ${contactListId} failed: ${String(err && err.message ? err.message : err).trim()}`)
        failedPartyIdList.push(id)
    }
}

const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
token = null
if (messageId) {
    const sent = ec.entity.find('mantle.marketing.contact.ContactListCommStatus').condition('messageId', messageId).one()
    if (sent != null) {
        if (!contactListId) contactListId = sent.contactListId
        if (!partyId) partyId = sent.partyId
        if (!contactMechId) contactMechId = sent.contactMechId
        if (!communicationEventId) communicationEventId = sent.communicationEventId
    }
}
if (!contactListId || !partyId) { ec.message.addError('An unsubscribe token needs a contactListId and a partyId'); return }
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
if (list == null) { ec.message.addError(`Contact list ${contactListId} not found`); return }
if (ec.entity.find('mantle.party.Party').condition('partyId', partyId).one() == null) { ec.message.addError(`Party ${partyId} not found`); return }
if (!contactMechId) contactMechId = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
        .condition('partyId', partyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list())
        .map((row) => row.preferredContactMechId).find((id) => id) || null
if (contactMechId && ec.entity.find('mantle.party.contact.PartyContactMech').condition({partyId: partyId, contactMechId: contactMechId}).count() === 0) {
    ec.message.addError(`Contact information ${contactMechId} is not party ${partyId}'s`); return }
if (!purposeEnumId) purposeEnumId = list.contactMechTypeEnumId === 'CmtTelecomNumber' ? 'PcpSms' : 'PcpMarketingEmail'
if (!thruDate && validDays) thruDate = new Date(toMillis(ec.user.nowTimestamp) + Number(validDays) * 86400000)
token = ec.user.randomString(32)
contactListTokenId = ec.service.sync().name('create#mantle.marketing.contact.ContactListToken').parameters({
    tokenHash: ec.user.singleUseCodeHash(token), contactListId: contactListId, partyId: partyId, contactMechId: contactMechId,
    communicationEventId: communicationEventId || null, messageId: messageId || null, purposeEnumId: purposeEnumId,
    createdDate: ec.user.nowTimestamp, thruDate: thruDate || null}).call()?.contactListTokenId ?? null
if (ec.message.hasError()) { token = null; return }
let root = String(baseUrl || '').trim()
if (!root) { try { root = ec.web ? String(ec.web.getWebappRootUrl(true, null) || '') : '' } catch (err) { root = '' } }
unsubscribeUrl = `${root.replace(/\/+$/, '')}/u/${token}`
// RFC 8058: the one-click POST goes to the List-Unsubscribe URL, the page a person opens to choose
oneClickUrl = unsubscribeUrl
const uris = [`<${oneClickUrl}>`]
const mailto = String(mailtoAddress || '').trim()
// one plain address: no display name, brackets, spaces or a query of its own
if (mailto && /^[^\s<>@?,;"]+@[^\s<>@?,;"]+$/.test(mailto)) uris.push(`<mailto:${mailto}?subject=${encodeURIComponent('unsubscribe ' + token)}>`)
else if (mailto) ec.logger.warn(`Unsubscribe token for party ${partyId} on list ${contactListId}: mailto address ${mailto} is not one plain address, left out`)
listUnsubscribeHeaders = {'List-Unsubscribe': uris.join(', '), 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click'}

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
valid = false
routeContext = null
const tokenText = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) return
const tokenRow = ec.entity.find('mantle.marketing.contact.ContactListToken').condition('tokenHash', ec.user.singleUseCodeHash(tokenText)).one()
if (tokenRow == null) return
valid = true
if (tokenRow.thruDate != null && toMillis(tokenRow.thruDate) <= toMillis(ec.user.nowTimestamp)) { routeContext = {expired: true}; return }
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', tokenRow.contactListId).one()
if (list == null) { routeContext = {expired: true}; return }
let organizationName = null
if (list.ownerPartyId) {
    const owner = ec.entity.find('mantle.party.PartyDetail').condition('partyId', list.ownerPartyId).one()
    organizationName = owner == null ? null : (owner.organizationName || ec.resource.expand('PartyFullNameTemplate', '', owner).trim() || null)
}
routeContext = {expired: false, organizationName: organizationName, contactListName: list.contactListName ?? null}

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
listList = []
// the token first, before anything else is read
const invalid = 'This unsubscribe link is not valid or has expired'
const tokenText = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) { ec.message.addError(invalid); return }
const tokenRow = ec.entity.find('mantle.marketing.contact.ContactListToken').condition('tokenHash', ec.user.singleUseCodeHash(tokenText)).one()
if (tokenRow == null || (tokenRow.thruDate != null && toMillis(tokenRow.thruDate) <= toMillis(ec.user.nowTimestamp))) { ec.message.addError(invalid); return }
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', tokenRow.contactListId).one()
if (list == null) { ec.message.addError(invalid); return }

if (list.ownerPartyId) {
    const owner = ec.entity.find('mantle.party.PartyDetail').condition('partyId', list.ownerPartyId).one()
    organizationName = owner == null ? null : (owner.organizationName || ec.resource.expand('PartyFullNameTemplate', '', owner).trim() || null)
}
contactListId = list.contactListId
contactListName = list.contactListName ?? null
listDescription = list.description ?? null
const state = ec.service.sync().name('mantle.party.ConsentServices.get#PartyConsentState').parameters({partyId: tokenRow.partyId,
    sameOwnerAsListId: list.contactListId, includeArchived: false}).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.message.addError(invalid); return }
const tokenEntry = (state.listList || []).find((entry) => entry.contactListId === list.contactListId) || null
statusId = tokenEntry?.statusId ?? null
subscribed = !!tokenEntry?.subscribed
unsubscribePending = !!tokenEntry?.unsubscribePending
const mechId = tokenRow.contactMechId || tokenEntry?.preferredContactMechId || null
marketingWithdrawn = (state.consentList || []).some((consent) => (consent.contactMechId || null) === mechId &&
        consent.purposeEnumId === 'PcpMarketingEmail' && consent.statusId === 'PconWithdrawn')
if (mechId) {
    const mech = ec.entity.find('mantle.party.contact.ContactMech').condition('contactMechId', mechId).one()
    if (mech?.contactMechTypeEnumId === 'CmtTelecomNumber') {
        const tn = ec.entity.find('mantle.party.contact.TelecomNumber').condition('contactMechId', mechId).one()
        const digits = String(tn?.contactNumber ?? '').replace(/[^0-9]/g, '')
        maskedAddress = digits ? `***${digits.slice(-Math.min(4, digits.length))}` : null
    } else if (mech?.infoString) {
        const [local, domain] = String(mech.infoString).split('@')
        maskedAddress = domain ? `${local.slice(0, 1)}***@${domain}` : `${String(mech.infoString).slice(0, 1)}***`
    }
}
listList = (state.listList || []).filter((entry) => entry.isCurrent && !entry.isArchived).map((entry) => ({contactListId: entry.contactListId,
    contactListName: entry.contactListName, description: entry.description, statusId: entry.statusId, subscribed: entry.subscribed,
    unsubscribePending: entry.unsubscribePending, isTokenList: entry.contactListId === list.contactListId}))
listList.sort((a, b) => (b.isTokenList ? 1 : 0) - (a.isTokenList ? 1 : 0))

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
changedList = []; failedContactListIds = []; marketingWithdrawn = false; unsubscribePending = false; verifyEmailSent = false
// the token first, before anything else is read
const invalid = 'This unsubscribe link is not valid or has expired'
const tokenText = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) { ec.message.addError(invalid); return }
const tokenRow = ec.entity.find('mantle.marketing.contact.ContactListToken').condition('tokenHash', ec.user.singleUseCodeHash(tokenText)).one()
if (tokenRow == null || (tokenRow.thruDate != null && toMillis(tokenRow.thruDate) <= toMillis(ec.user.nowTimestamp))) { ec.message.addError(invalid); return }

if (unsubscribeAll) {
    const out = ec.service.sync().name('mantle.party.ConsentServices.unsubscribe#ContactListParty')
            .parameters({token: tokenText, allMarketing: true, reasonText: reasonText || null, baseUrl: baseUrl || null}).call()
    if (ec.message.hasError()) return
    changedList = out.changedList || []
    failedContactListIds = out.failedContactListIds || []
    marketingWithdrawn = !!out.marketingWithdrawn
    unsubscribePending = !!out.unsubscribePending
    verifyEmailSent = !!out.verifyEmailSent
    return
}

const truthy = (value) => value === true || ['true', 'y', 'yes', '1', 'on'].includes(String(value ?? '').trim().toLowerCase())
let choices = []
if (Array.isArray(listChoices) || (listChoices != null && typeof listChoices.length === 'number' && typeof listChoices !== 'string')) {
    choices = Array.from(listChoices).map((choice) => ({contactListId: choice?.contactListId, subscribed: truthy(choice?.subscribed)}))
} else if (listChoices != null && typeof listChoices === 'object') {
    choices = Object.entries(listChoices).map(([id, value]) => ({contactListId: id, subscribed: truthy(value)}))
}
const state = ec.service.sync().name('mantle.party.ConsentServices.get#PartyConsentState').parameters({partyId: tokenRow.partyId,
    sameOwnerAsListId: tokenRow.contactListId, includeArchived: false}).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.message.addError(invalid); return }
const offered = new Map((state.listList || []).filter((entry) => entry.isCurrent && !entry.isArchived).map((entry) => [entry.contactListId, entry]))
// a Message-ID without its angle brackets, which the evidence parameters take as markup
const evidence = 'Unsubscribe page preferences' + (tokenRow.messageId ? ` of message ${String(tokenRow.messageId).replace(/[<>]/g, '')}` : '')
for (const choice of choices) {
    const id = choice.contactListId ? String(choice.contactListId) : ''
    const entry = offered.get(id)
    if (entry == null) {
        ec.logger.warn(`Unsubscribe preferences: contact list ${id} is not one offered for token ${tokenRow.contactListTokenId}, skipped`)
        failedContactListIds.push(id)
        continue
    }
    if (choice.subscribed ? entry.subscribed : ['CLPT_UNSUBSCRIBED', 'CLPT_UNSUBS_PENDING'].includes(entry.statusId)) continue
    try {
        const out = ec.service.sync().name('mantle.party.ConsentServices.set#ContactListPartySubscription').parameters({contactListId: id,
            partyId: tokenRow.partyId, subscribe: choice.subscribed, contactMechId: tokenRow.contactMechId || null,
            sourceEnumId: 'PcsEmailLink', evidenceText: evidence, comments: choice.subscribed ? null : (reasonText || null),
            baseUrl: baseUrl || null}).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        if (out.statusId === 'CLPT_UNSUBS_PENDING') unsubscribePending = true
        if (out.verifyEmailSent) verifyEmailSent = true
        if (out.changed) changedList.push({contactListId: id, statusId: out.statusId, previousStatusId: out.previousStatusId})
    } catch (err) {
        ec.message.clearErrors()
        ec.logger.error(`Unsubscribe preferences: contact list ${id} for token ${tokenRow.contactListTokenId} failed: ${String(err && err.message ? err.message : err).trim()}`)
        failedContactListIds.push(id)
    }
}
tokenRow.set('usedDate', ec.user.nowTimestamp)
tokenRow.update()
